    rec_base('چارچوب\u200cهای ایزوتسو و فیلمور و معناشناسیِ شناختی در این آیه چنین به کار می\u200cآیند که مدار عداوت را می\u200cخواند و این کاربرد چارچوب\u200cمند است و جای نقلِ مستقیمِ منبع را نمی\u200cگیرد.', J_TATBIQ),
